def maior(v, ini, fim):
    if fim - ini == 1:
        return v[ini]
    meio = (ini + fim) // 2
    esquerda = maior(v, ini, meio)
    direita = maior(v, meio, fim)
    return max(esquerda, direita)

print(maior([7, 2, 9, 4, 1, 8, 3, 6], 0, 8))

